            {"metric": "backward 전체 실행 시간", "value": "98.995", "value_kind": "scalar", "unit": "s", "condition": "40000개 데이터 테스트, CROWN_SWEEP 프로파일링", "element_ids": ["p47:e337", "p47:img3:e0"]}
          ],
          "element_ids": ["p47:e337", "p47:e338", "p47:img1:e0", "p47:img3:e0"]
